import org.openenglish.reader.ReadingProgress;import org.json.*;
public final class ReadingProgressTest {
 static int checks;static void ok(boolean b,String message){if(!b)throw new AssertionError(message);checks++;}
 static void invalid(String raw)throws Exception{try{ReadingProgress.validate(raw);throw new AssertionError("invalid state accepted");}catch(JSONException expected){checks++;}}
 public static void main(String[] args)throws Exception{
  JSONObject s=ReadingProgress.fresh();ReadingProgress.validate(s.toString());checks++;
  ReadingProgress.rollDay(s,"2026-10-12");s.put("seconds",599);ok(!ReadingProgress.finish(s,"2026-10-12"),"short sessions cannot complete");s.put("seconds",600);ok(ReadingProgress.finish(s,"2026-10-12"),"ten minute session completes");ok(!ReadingProgress.finish(s,"2026-10-12"),"duplicate daily completion rejected");ok(s.getInt("completed")==1,"duplicate does not advance route");ReadingProgress.rollDay(s,"2026-10-13");ok(s.getInt("seconds")==0&&s.getInt("completed")==1,"new day resets timer only");s.put("seconds",600);ok(ReadingProgress.finish(s,"2026-10-13"),"next day advances");s.put("completed",18);ReadingProgress.rollDay(s,"2026-10-14");s.put("seconds",600);ok(!ReadingProgress.finish(s,"2026-10-14"),"route bounded at eighteen");
  JSONObject c=new JSONObject().put("zh","站台").put("due",0).put("interval",0).put("reviews",0);long now=1000000;int[] expected={1,2,4,8,16,30,30};for(int days:expected){c=ReadingProgress.review(c,true,now);ok(c.getInt("interval")==days&&c.getLong("due")==now+days*86400000L,"spaced repetition schedule");}c=ReadingProgress.review(c,false,now);ok(c.getLong("due")==now+600000&&c.getInt("interval")==0,"forgotten card retries in ten minutes");s.getJSONObject("cards").put("platform",c);s.getJSONObject("positions").put("station",2);ReadingProgress.validate(s.toString());JSONObject restored=new JSONObject(s.toString());ok(restored.getJSONObject("positions").getInt("station")==2&&restored.getJSONObject("cards").getJSONObject("platform").getInt("reviews")==8,"backup round trip retains reading position and cards");
  invalid(new JSONObject(s.toString()).put("version",2).toString());invalid(new JSONObject(s.toString()).put("completed",19).toString());invalid(new JSONObject(s.toString()).put("seconds",-1).toString());invalid(new JSONObject(s.toString()).put("secret","x").toString());JSONObject bad=new JSONObject(s.toString());bad.getJSONObject("cards").getJSONObject("platform").put("due",-1);invalid(bad.toString());bad=new JSONObject(s.toString());bad.getJSONObject("positions").put("../path",2);invalid(bad.toString());invalid("not-json");
  System.out.println("Reading progress checks passed: "+checks);
 }
}
